def contribution(price, bom, gst, ship=90):
    landed = bom * 1.08; net = price / (1 + gst); fees = price * (0 if price < 1000 else 0.08) + 30 + ship
    c = net - landed - fees - net * 0.12 - 0.08 * landed; return c, c / net
